import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { InterfClasificacion } from '../../interfaces/interf-clasificacion';
import { global } from '../global_ssic';
import { Usuarios } from '../../modelos/Usuarios';

@Injectable({
  providedIn: 'root'
})
export class ContrasenaServiceService {
  public url: string;
  public user:any;
  httpOptions = {
    Headers: new HttpHeaders({
      'Content-Type': 'application/json'
    })
  }

  constructor(private _httpClient: HttpClient) {
    this.url = global.urlApi;
    this.user = sessionStorage.getItem('inside_session_code');
  }

  getFondoPantalla(){
    var headers = 'data:image/png;base64,';
    return headers;
  }

  sendPasswordSSIC(passPrimera:any,passSegunda:any,passOlder:any):Observable<any>{
    let headers = new HttpHeaders().set('Content-Type','application/x-www-form-urlencoded');
    let json = JSON.stringify({"user_token":sessionStorage.getItem('inside_session_code'),"passPrimera":passPrimera,"passSegunda":passSegunda,"passOlder":passOlder});
    console.log(json);
    let parametros = 'json='+json;
    return this._httpClient.post(this.url+'module_ssic_updatepass',parametros,{headers: headers})
    .pipe(catchError(this.handlerError))
  }

  sendPasswordGP(passPrimera:any,passSegunda:any,passOlder:any):Observable<any>{
    let headers = new HttpHeaders().set('Content-Type','application/x-www-form-urlencoded');
    let json = JSON.stringify({"user_token":sessionStorage.getItem('inside_session_code'),"passPrimera":passPrimera,"passSegunda":passSegunda,"passOlder":passOlder});
    console.log(json);
    let parametros = 'json='+json;
    return this._httpClient.post(this.url+'updatepass_module_gestion_proyectos',parametros,{headers: headers})
    .pipe(catchError(this.handlerError))
  }

  handlerError(error: { error: { message: string; }; status: any; message: any; }){
		let errorMessage = 'Ocurrió un error inesperado. Intente más tarde.';
		if(error.error instanceof ErrorEvent){
			errorMessage = `Error: ${error.error.message}`;
		} else {
      errorMessage = error.error.message;
		}
		return throwError(errorMessage);
	}
}
